import{z as s,x as l,o as B,c as d,q as n,j as r,D as A,d as t,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"供应商对接","description":"","frontmatter":{"title":"供应商对接","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-vendor-integration.md","filePath":"quant/de-vendor-integration.md","lastUpdated":1791063341000}'),C={name:"quant/de-vendor-integration.md"};function D(F,E,p,u,g,h){const e=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="供应商对接" tabindex="-1">供应商对接 <a class="header-anchor" href="#供应商对接" aria-label="Permalink to &quot;供应商对接&quot;">​</a></h1><div class="epigraph"><p>两家内容几乎相同的供应商，一家留历次快照、一家就地覆盖修正；对点时研究而言，这不是两家厂商，是两种物理定律。</p><footer>—— 据 Bloomberg、LSEG（Refinitiv）等供应商公开的数据使用条款与修订政策口径整理</footer></div><p><a href="/quant/de-quality-monitoring">上一课</a>的监控能发现质量问题，但多数质量问题的源头不在管道里，在合同里：字段怎么定义、修正怎么交付、晚到怎么补偿，都是对接那一刻谈定的。本课写对接的工程与治理：从许可到切换到退役的生命周期。<a href="/quant/data-vendors">数据供应商对照</a>比较过各家数据内容的取舍，本课比较契约与修订政策——那半张更重要的清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对接的失败模式有四个，都在切换之后才显形。<strong>契约真空</strong>：没写清时间戳语义、修正政策、晚到的处理，出问题只能靠邮件考古。<strong>修订政策误配</strong>：研究需要 vintage，供应商交付的却是「终版回填」，错误在交付那一刻已铸成，<a href="/quant/data-acquisition-audit">数据获取与审计</a>的降级口径是唯一出路。<strong>幂等缺失</strong>：日终文件重推一次，成交量翻倍；增量补丁乱序应用，某几天成了几代口径的拼盘。<strong>锁定</strong>：唯一来源、私有键、按用量计价，退出成本逐年上升，议价与对账能力同步归零。</p><p><span class="marginnote">术语翻译：vintage（Vintage 数据，即「时点版本」）就是每次快照都留底、永不覆盖——3 月 5 日拿到的 2025 年报数据是 v1，供应商 6 月修正后是 v2，两版都保留。终版回填则是拿 v2 直接覆盖 v1。研究回测必须用「当时能看到的那一版」，被覆盖过的历史就再也还原不回去了。</span></p><h3 id="对接要谈的六项契约" tabindex="-1">对接要谈的六项契约 <a class="header-anchor" href="#对接要谈的六项契约" aria-label="Permalink to &quot;对接要谈的六项契约&quot;">​</a></h3><p>字段字典（含义、单位、空值语义）；时间戳语义；修正与重述政策；交付方式（批量文件、API、推送流）与频率；SLA（到达时限、晚到补偿、历史回补义务）；许可（用途、转发、派生数据、留存）。最常被跳过的是修正政策与回补义务——恰好是 PIT 研究的命门。</p><p><span class="marginnote">切量级之前先切合同：供应商升级字段定义属于单方变更时，合同里有没有「提前通知与双轨并行期」条款，决定你是平滑迁移还是紧急救火——技术上的影子对比，要靠合同里的并行期才做得了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生命周期五段。<strong>一，许可与合规前置</strong>：用途、转发、派生与留存先过法务，爬虫类另类源沿用<a href="/quant/alt-crawler-compliance">爬虫的合规与工程</a>的口径，许可不清不进试运行。<strong>二，契约落纸</strong>：六项写成对接附录，字段字典进平台元数据层，供应商改字段定义等同新字段。<strong>三，影子摄取</strong>：新源先旁路接入，与主源并行双跑一到三个月，按<a href="/quant/de-quality-monitoring">数据质量监控</a>的对账口径逐日比对，差异定位到字段与日期，解释不了的入风险清单。<strong>四，切换与退役</strong>：切换日发新数据版本，旧版本只读归档，实验显式迁移——走<a href="/quant/de-data-versioning">数据版本化</a>的发布流程。<strong>五，持续治理</strong>：每季度重跑审计清单、复核 SLA；批量文件要幂等键与乱序保护，推送流要会话恢复，二进制协议见<a href="/quant/binary-protocols-ouch-sbe">二进制协议：OUCH 与 SBE</a>。</p>',11)),(B(),r(i,null,{default:A(()=>[o(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIC%5B%22%E8%AE%B8%E5%8F%AF%E4%B8%8E%E5%90%88%E8%A7%84%E5%89%8D%E7%BD%AE%22%5D%20--%3E%20CON%5B%22%E5%A5%91%E7%BA%A6%E5%85%AD%E9%A1%B9%E8%90%BD%E7%BA%B8%EF%BC%9A%E5%AD%97%E5%85%B8%E3%80%81%E6%97%B6%E6%88%B3%E3%80%81%E4%BF%AE%E6%AD%A3%E3%80%81%E4%BA%A4%E4%BB%98%E3%80%81SLA%E3%80%81%E8%AE%B8%E5%8F%AF%22%5D%0A%20%20CON%20--%3E%20SH%5B%22%E5%BD%B1%E5%AD%90%E6%91%84%E5%8F%96%EF%BC%9A%E4%B8%8E%E4%B8%BB%E6%BA%90%E5%B9%B6%E8%A1%8C%E5%8F%8C%E8%B7%91%22%5D%0A%20%20SH%20--%3E%7C%22%E5%B7%AE%E5%BC%82%E5%8F%AF%E8%A7%A3%E9%87%8A%22%7C%20CUT%5B%22%E5%88%87%E6%8D%A2%EF%BC%9A%E5%8F%91%E6%96%B0%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%22%5D%0A%20%20SH%20--%3E%7C%22%E5%B7%AE%E5%BC%82%E4%B8%8D%E5%8F%AF%E8%A7%A3%E9%87%8A%22%7C%20RISK%5B%22%E9%A3%8E%E9%99%A9%E6%B8%85%E5%8D%95%EF%BC%9A%E9%99%8D%E7%BA%A7%E6%88%96%E6%94%BE%E5%BC%83%22%5D%0A%20%20CUT%20--%3E%20OLD%5B%22%E6%97%A7%E6%BA%90%E5%8F%AA%E8%AF%BB%E5%BD%92%E6%A1%A3%22%5D%0A%20%20CUT%20--%3E%20GOV%5B%22%E6%8C%81%E7%BB%AD%E6%B2%BB%E7%90%86%EF%BC%9A%E5%AD%A3%E5%BA%A6%E9%87%8D%E5%AE%A1%20%2B%20SLA%20%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20GOV%20--%3E%7C%22%E5%8D%95%E6%96%B9%E5%8F%98%E6%9B%B4%22%7C%20SH%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"对接的机制要点是「把外部依赖变成内部契约」。供应商的世界没有义务保持稳定，平台的职责是在边界处把不稳定翻译成自己已知的两样东西：不可变版本与显式契约。有了这两样，供应商的任何变化——字段变义、修正回填、交付延迟——都会撞在监控的断言上，而不是撞在三个月后的回测上；断言守的是契约的执行，不是供应商的善意。多源策略同理：第二来源是对账锚而非冗余主源，两套主源并存会制造「选哪个数」的成本，一主一锚让分歧本身成为可监控的量。锁定则要在买第一个数据集时就想：私有键进不了永久实体键体系的数据，接进来一天，退出成本就涨一天。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：幂等键就是给每份交付盖的「防重印章」。某日终文件的幂等键若是「源 × 表 × 交易日 × 批次号」，供应商重推同一天时平台查到印章已存在、直接丢弃，成交量仍是 1,284,300 股；没有幂等键而用追加写入，同一行落两遍，成交量变 2,568,600 股——数值合理、无报错，坏得无声无息。")],-1)),(B(),r(i,null,{default:A(()=>[o(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E6%89%B9%E6%AC%A1%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20KEY%5B%22%E6%8F%90%E5%8F%96%E5%B9%82%E7%AD%89%E9%94%AE%EF%BC%9A%E6%BA%90%20%C3%97%20%E8%A1%A8%20%C3%97%20%E4%BA%A4%E6%98%93%E6%97%A5%20%C3%97%20%E6%89%B9%E6%AC%A1%22%5D%0A%20%20KEY%20--%3E%20SEEN%7B%22%E9%94%AE%E5%B7%B2%E5%A4%84%E7%90%86%E8%BF%87%EF%BC%9F%22%7D%0A%20%20SEEN%20--%3E%7C%22%E6%98%AF%EF%BC%88%E9%87%8D%E6%8E%A8%EF%BC%89%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%EF%BC%9A%E5%86%99%E5%AE%A1%E8%AE%A1%E6%97%A5%E5%BF%97%22%5D%0A%20%20SEEN%20--%3E%7C%22%E5%90%A6%22%7C%20ORD%7B%22%E8%A1%A5%E4%B8%81%E5%BA%8F%E5%8F%B7%E8%BF%9E%E7%BB%AD%EF%BC%9F%22%7D%0A%20%20ORD%20--%3E%7C%22%E4%B9%B1%E5%BA%8F%22%7C%20BUF%5B%22%E6%9A%82%E5%AD%98%E7%BC%93%E5%86%B2%EF%BC%9A%E7%AD%89%E7%BC%BA%E5%8F%A3%E8%A1%A5%E9%BD%90%22%5D%0A%20%20BUF%20--%3E%20ORD2%7B%22%E7%AD%89%E5%BE%85%E8%B6%85%E6%97%B6%EF%BC%9F%22%7D%0A%20%20ORD2%20--%3E%7C%22%E6%98%AF%22%7C%20ALM%5B%22%E5%91%8A%E8%AD%A6%EF%BC%9A%E7%94%B3%E8%AF%B7%E5%9B%9E%E8%A1%A5%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20ORD2%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E8%A1%A5%E9%BD%90%22%7C%20APP%5B%22%E6%8C%89%E5%BA%8F%E5%BA%94%E7%94%A8%20%2B%20%E8%AE%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20ORD%20--%3E%7C%22%E8%BF%9E%E7%BB%AD%22%7C%20APP%0A%20%20APP%20--%3E%20OK%5B%22%E5%85%A5%E5%BA%93%EF%BC%9A%E9%87%8D%E6%8E%A8%E5%AE%89%E5%85%A8%EF%BC%8C%E4%B9%B1%E5%BA%8F%E5%8F%AF%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">常见误区：初学者容易把第二来源当成「主源挂了顶上」的热备。实际上两家供应商对同一字段天然存在口径差（复权方式、时间戳精度、停牌处理各不相同），互为备份只会让每次切换都在换口径。第二来源的正确用法是只做对账：两源日对日比价，分歧本身成为一条告警线，主源永远唯一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较各供应商的数据内容与覆盖，见<a href="/quant/data-vendors">数据供应商对照</a>；不谈采购议价与预算。影子期再长也买不回历史：新源宣称的覆盖与质量，以抽样回测验证而非以文档为准。合规边界永久有效：许可过期的历史数据按合同处置，不是「下线了但还在硬盘里」。对接成本常被低估：新供应商从签约到可信通常以季度计，要当成工程里程碑而不是一次下载。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对接的核心是把外部依赖翻译成内部契约：六项条款落纸，字段字典进元数据层。</li><li>修订政策是 PIT 的命门：合同拿不到 vintage，就按审计口径显式降级。</li><li>摄取必须幂等：重推不重复，补丁可乱序恢复。</li><li>影子双跑后才切换，切换即发布新版本，旧源只读归档。</li><li>第二来源做对账锚，不做冗余主源；私有键是锁定的开始。</li><li>出处：Bloomberg、LSEG（Refinitiv）公开数据条款口径；站内<a href="/quant/data-vendors">数据供应商对照</a>、<a href="/quant/data-acquisition-audit">数据获取与审计</a>。</li></ul>',5))])}const q=s(C,[["render",D]]);export{f as __pageData,q as default};
